import { useState, useEffect } from 'react';
import { TranscriptCue, Chapter } from '../types/player';
import { parseVtt, parseChaptersVtt } from '../utils/videoUtils';

export const useTranscriptData = (captions?: string, description?: string) => {
  const [cues, setCues] = useState<TranscriptCue[]>([]);

  useEffect(() => {
    let cap: TranscriptCue[] = [];
    let desc: TranscriptCue[] = [];
    (async () => {
      if (captions) {
        const txt = await fetch(captions).then(r => r.text());
        cap = parseVtt(txt, 'caption');
      }
      if (description) {
        const txt = await fetch(description).then(r => r.text());
        desc = parseVtt(txt, 'description');
      }
      setCues([...cap, ...desc].sort((a, b) => a.start - b.start));
    })();
  }, [captions, description]);

  return cues;
};

export const useChaptersData = (chapters?: string) => {
  const [parsedChapters, setParsedChapters] = useState<Chapter[]>([]);

  useEffect(() => {
    if (!chapters) return;
    fetch(chapters)
      .then(r => r.text())
      .then(txt => setParsedChapters(parseChaptersVtt(txt)));
  }, [chapters]);

  return parsedChapters;
};

export const useVoicesData = () => {
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [selectedVoice, setSelectedVoice] = useState('');

  useEffect(() => {
    const updateVoices = () => {
      const vs = window.speechSynthesis.getVoices();
      setVoices(vs);
      if (!selectedVoice && vs.length > 0) setSelectedVoice(vs[0].voiceURI);
    };
    updateVoices();
    window.speechSynthesis.onvoiceschanged = updateVoices;
  }, [selectedVoice]);

  return { voices, selectedVoice, setSelectedVoice };
};