"use client"

import React, { useRef, useState } from 'react';
import { FullPlayerProps } from '../types/player';
import { usePlayerState } from '../hooks/usePlayerState';
import { usePlayerEffects } from '../hooks/usePlayerEffects';
import { usePlayerControls } from '../hooks/usePlayerControls';
import { useTranscriptData, useChaptersData } from '../hooks/useVideoData';
import { PlayerContainer } from './PlayerContainer';
import { PlayerControls } from './PlayerControls';
import { PlayerModals } from './PlayerModals';
import { PlayerSidebar } from './PlayerSidebar';
import { formatTime, addPlayerStyles } from '../utils/videoUtils';
import { LOCAL } from '../app/layout';

const FullPlayer: React.FC<FullPlayerProps> = ({ 
  mp4, 
  webm, 
  youtube, 
  vimeo, 
  btag, 
  captions, 
  description, 
  chapters, 
  autoplay = false, 
  muted = true 
}) => {
  // Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const controlsRef = useRef<HTMLDivElement>(null);
  const youtubeContainerRef = useRef<HTMLDivElement>(null);
  const vimeoContainerRef = useRef<HTMLDivElement>(null);

  // Custom hooks for state management
  const playerState = usePlayerState({ autoplay, muted });
  const playerControls = usePlayerControls({ 
    videoRef, 
    youtubeContainerRef, 
    vimeoContainerRef,
    playerState 
  });

  // Data hooks
  const cues = useTranscriptData(captions, description);
  const parsedChapters = useChaptersData(chapters);

  // Effects
  usePlayerEffects({
    mp4,
    webm,
    youtube,
    vimeo,
    btag,
    captions,
    description,
    chapters,
    playerState,
    playerControls,
    cues,
    parsedChapters,
    videoRef,
    youtubeContainerRef,
    vimeoContainerRef
  });

  // Feature availability based on LOCAL
  const hasCC = !!captions && captions.includes(`_${LOCAL}.vtt`);
  const hasTranscript = !!description && description.includes(`_${LOCAL}.vtt`);
  const hasAudioDesc = !!description || playerState.hasAudioTrack;

  return (
    <section 
      aria-label="Barrierefreier Video Player" 
      style={{ 
        maxWidth: '100%', 
        display: 'flex', 
        flexDirection: 'row', 
        alignItems: 'flex-start', 
        gap: 16 
      }}
    >
      <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>
        
        {/* Video Container */}
        <PlayerContainer
          videoRef={videoRef}
          youtubeContainerRef={youtubeContainerRef}
          vimeoContainerRef={vimeoContainerRef}
          playerState={playerState}
          mp4={mp4}
          webm={webm}
          captions={captions}
          description={description}
          chapters={chapters}
        />

        {/* Progress Bar */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8, width: '100%' }}>
          <span style={{ minWidth: 48, textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontSize: 14 }}>
            {formatTime(playerState.currentTime)}
          </span>
          <input
            type="range"
            min={0}
            max={playerState.duration || 1}
            step={0.01}
            value={playerState.currentTime}
            onChange={e => playerControls.handleSeek(Number(e.target.value))}
            aria-label="Fortschritt"
            style={{ 
              flex: 1, 
              height: 6,
              borderRadius: 3,
              background: `linear-gradient(to right, #007acc 0%, #007acc ${(playerState.currentTime / playerState.duration) * 100}%, #ddd ${(playerState.currentTime / playerState.duration) * 100}%, #ddd 100%)`
            }}
          />
          <span style={{ minWidth: 48, textAlign: 'left', fontVariantNumeric: 'tabular-nums', fontSize: 14 }}>
            {formatTime(playerState.duration)}
          </span>
        </div>

        {/* Controls */}
        <PlayerControls
          playerState={playerState}
          playerControls={playerControls}
          hasCC={hasCC}
          hasTranscript={hasTranscript}
          hasAudioDesc={hasAudioDesc}
          hasChapters={!!chapters}
        />

        {/* Sidebar */}
        <PlayerSidebar
          playerState={playerState}
          cues={cues}
          parsedChapters={parsedChapters}
          onChapterClick={playerControls.handleChapterClick}
        />
      </div>

      {/* Modals */}
      <PlayerModals
        playerState={playerState}
        hasCC={hasCC}
        hasTranscript={hasTranscript}
      />
    </section>
  );
};

export default FullPlayer;