import { useState } from 'react';

interface UsePlayerStateProps {
  autoplay: boolean;
  muted: boolean;
}

export const usePlayerState = ({ autoplay, muted }: UsePlayerStateProps) => {
  // Basic player state mit korrekten Defaults
  const [isPlaying, setIsPlaying] = useState(!autoplay); // Standard: Pause
  const [isMuted, setIsMuted] = useState(muted); // Standard: Ton aus
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1); // Standard: 100%
  const [playbackRate, setPlaybackRate] = useState(1); // Standard: 1x
  const [controlsVisible, setControlsVisible] = useState(true);
  const [isPiPSupported, setIsPiPSupported] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // UI state mit korrekten Defaults
  const [showTranscript, setShowTranscript] = useState(false);
  const [showCC, setShowCC] = useState(false);
  const [showChapters, setShowChapters] = useState(false); // Standard: off
  const [isSpooling, setIsSpooling] = useState(false);

  // Modal states
  const [audioDescSettingsOpen, setAudioDescSettingsOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [infoOpen, setInfoOpen] = useState(false);

  // Audio description state
  const [audioDescActive, setAudioDescActive] = useState(false);
  const [ttsBusy, setTtsBusy] = useState(false);
  const [pitch, setPitch] = useState(1);
  const [autoStop, setAutoStop] = useState(true);
  const [autoStart, setAutoStart] = useState(true);
  const [audioDescMode, setAudioDescMode] = useState<'tts' | 'audio' | 'sign'>('tts');
  const [ttsAvailable, setTtsAvailable] = useState(true);
  const [ttsError, setTtsError] = useState('');
  const [hasAudioTrack, setHasAudioTrack] = useState(false);
  const [hasSignTrack, setHasSignTrack] = useState(false);

  // Content indexes
  const [currentCueIdx, setCurrentCueIdx] = useState<number>(-1);
  const [currentChapterIdx, setCurrentChapterIdx] = useState(-1);

  // Video sources and quality
  const [videoSources, setVideoSources] = useState<any>({});
  const [selectedQuality, setSelectedQuality] = useState<string>('auto');
  const [videoSrc, setVideoSrc] = useState<string>('');
  const [availableQualities, setAvailableQualities] = useState<any[]>([]);

  // Player type state
  const [playerType, setPlayerType] = useState<'video' | 'youtube' | 'vimeo' | 'btag'>('video');

  return {
    // Basic state
    isPlaying, setIsPlaying,
    isMuted, setIsMuted,
    currentTime, setCurrentTime,
    duration, setDuration,
    volume, setVolume,
    playbackRate, setPlaybackRate,
    controlsVisible, setControlsVisible,
    isPiPSupported, setIsPiPSupported,
    isLoading, setIsLoading,

    // UI state
    showTranscript, setShowTranscript,
    showCC, setShowCC,
    showChapters, setShowChapters,
    isSpooling, setIsSpooling,

    // Modals
    audioDescSettingsOpen, setAudioDescSettingsOpen,
    settingsOpen, setSettingsOpen,
    infoOpen, setInfoOpen,

    // Audio description
    audioDescActive, setAudioDescActive,
    ttsBusy, setTtsBusy,
    pitch, setPitch,
    autoStop, setAutoStop,
    autoStart, setAutoStart,
    audioDescMode, setAudioDescMode,
    ttsAvailable, setTtsAvailable,
    ttsError, setTtsError,
    hasAudioTrack, setHasAudioTrack,
    hasSignTrack, setHasSignTrack,

    // Content
    currentCueIdx, setCurrentCueIdx,
    currentChapterIdx, setCurrentChapterIdx,

    // Video sources
    videoSources, setVideoSources,
    selectedQuality, setSelectedQuality,
    videoSrc, setVideoSrc,
    availableQualities, setAvailableQualities,
    playerType, setPlayerType
  };
};